      "card_ids": ["C18"],
      "claim": "Tetrabenazine, the closest analogue (Morgan 0.3731), had a mean oral systemic availability of only 0.049 ± 0.032 in patients, directly indicating very low oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C30"],
      "claim": "Almorexant, a moderately similar analogue, had an absolute oral bioavailability of 11.2% (90% CI 9.6–13.1) in healthy subjects, supporting low oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C36"],
      "claim": "Verapamil, a less similar analogue, averaged 19.4% oral bioavailability in normal young men, just below the 20% threshold, weakly supporting low oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Valbenazine, a less similar analogue, had an absolute oral bioavailability of approximately 49% in humans, which would support high oral bioavailability but transfers with lower weight.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C19"],
      "claim": "Donepezil, a less similar analogue, had an oral bioavailability of 100% in humans, supporting high oral bioavailability but with lower transferability.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
